alter table public.companies add column if not exists asset_accounting_method text check (asset_accounting_method is null or asset_accounting_method in ('chart_of_accounts','without_chart_of_accounts'));
alter table public.asset_categories add column if not exists company_id uuid references public.companies(id) on delete cascade, add column if not exists description text, add column if not exists depreciation_method text, add column if not exists useful_life_years numeric, add column if not exists residual_value numeric not null default 0, add column if not exists is_active boolean not null default true;
create index if not exists asset_categories_company_idx on public.asset_categories(company_id);
create table if not exists public.asset_assignments (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,asset_id uuid not null references public.fixed_assets(id) on delete cascade,assignment_code text,employee_id uuid,employee_name text not null,issue_date date not null,expected_return_date date,actual_return_date date,condition_at_issue text,condition_at_return text,status text not null default 'Issued' check(status in ('Issued','Returned','Lost')),acknowledgement text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists asset_assignments_company_asset_idx on public.asset_assignments(company_id,asset_id);
create table if not exists public.asset_maintenance_records (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,asset_id uuid not null references public.fixed_assets(id) on delete cascade,maintenance_number text,maintenance_type text not null default 'Repair',priority text not null default 'Medium',reported_date date not null default current_date,due_date date,provider text,estimated_cost numeric not null default 0,actual_cost numeric not null default 0,status text not null default 'Open' check(status in ('Open','In Progress','Completed','Cancelled')),description text,resolution text,next_service_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists asset_maintenance_company_asset_idx on public.asset_maintenance_records(company_id,asset_id);
create table if not exists public.asset_transfers (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,asset_id uuid not null references public.fixed_assets(id) on delete cascade,transfer_date date not null,from_location text,to_location text,from_department text,to_department text,from_custodian text,to_custodian text,reason text,created_at timestamptz not null default now());
create index if not exists asset_transfers_company_asset_idx on public.asset_transfers(company_id,asset_id);
create table if not exists public.asset_disposals (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,asset_id uuid not null references public.fixed_assets(id) on delete cascade,disposal_date date not null,disposal_type text not null default 'Sale',sale_value numeric not null default 0,accumulated_depreciation numeric not null default 0,book_value_at_disposal numeric not null default 0,profit_loss numeric not null default 0,reason text,buyer_name text,reference_number text,created_at timestamptz not null default now());
create index if not exists asset_disposals_company_asset_idx on public.asset_disposals(company_id,asset_id);
create table if not exists public.asset_depreciation_entries (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,asset_id uuid not null references public.fixed_assets(id) on delete cascade,period_start date not null,period_end date not null,method text not null,depreciation_amount numeric not null default 0,opening_book_value numeric not null default 0,closing_book_value numeric not null default 0,voucher_id uuid references public.accounting_vouchers(id) on delete set null,status text not null default 'Calculated' check(status in ('Calculated','Posted','Reversed')),created_at timestamptz not null default now(),unique(company_id,asset_id,period_start,period_end));
create index if not exists asset_depreciation_company_period_idx on public.asset_depreciation_entries(company_id,period_start,period_end);
do $$ declare tbl text; begin foreach tbl in array array['asset_assignments','asset_maintenance_records','asset_transfers','asset_disposals','asset_depreciation_entries'] loop execute format('alter table public.%I enable row level security',tbl); execute format('create policy %I on public.%I for all to authenticated using (private.is_company_owner(company_id) or private.has_company_user_permission(company_id, ''hr'', false) or private.has_company_user_permission(company_id, ''accounting'', false) or private.has_ca_company_access(company_id, false)) with check (private.is_company_owner(company_id) or private.has_company_user_permission(company_id, ''hr'', true) or private.has_company_user_permission(company_id, ''accounting'', true) or private.has_ca_company_access(company_id, true))',tbl||'_company_access',tbl); end loop; end $$;